const cleanCompany=(nm)=>{if(!nm)return'';const orig=String(nm).trim();let c=orig;
const GEN=new Set(['home','welcome','shop','store','about','about us','products','index','page','contact','contact us','blog','news']);
const isGen=(s)=>GEN.has(String(s).trim().toLowerCase());
const pick=(a)=>{for(const p of a){if(p&&String(p).trim()&&!isGen(p))return String(p).trim();}return null;};
c=c.replace(/^welcome to\s+/i,'').trim();
const pp=c.split(' | '); if(pp.length>1){const s=pick(pp); if(s===null) return orig; c=s;}
for(let i=0;i<2;i++){const d=c.search(/\s[-–—]\s/); if(d<3) break; const head=c.slice(0,d).trim(); const tail=c.slice(d).replace(/^\s[-–—]\s/,'').trim(); const s=pick([head,tail]); if(s===null) return orig; c=s;}
if(/^[A-Za-z0-9][A-Za-z0-9-]*(\.[A-Za-z]{2,})+$/.test(c)) c=c.replace(/(\.[A-Za-z]{2,})+$/,'');
c=c.replace(/[®™]/g,'');
for(let i=0;i<2;i++){c=c.replace(/[,\s]+(inc|llc|l\.l\.c\.|ltd|limited|corp|corporation|co|company|gmbh|plc|llp|lp|pllc|pc)\.?$/i,'').trim();}
c=c.replace(/,+$/,'').trim();
const hasUp=/\p{Lu}/u.test(c), hasLow=/\p{Ll}/u.test(c);
if(hasUp!==hasLow){const parts=c.split(/(\s+)/); const words=parts.filter(t=>/\S/.test(t)); const MINOR=new Set(['of','and','the','for','to','in','on','at','by','a','an']);
if(!(hasUp&&words.length===1&&c.length<=4)){let wi=-1; c=parts.map(t=>{if(!/\S/.test(t))return t; wi++; const lw=t.toLowerCase(); return (wi>0&&MINOR.has(lw))?lw:lw.replace(/\p{L}/u,(ch)=>ch.toUpperCase());}).join('');}}
return c;};
const BLACK = new Set(['hr','careers','career','jobs','job','legal','privacy','noreply','no-reply','donotreply','abuse','postmaster','compliance','recruiting','recruitment','press','media','unsubscribe','webmaster','admin','info-security']);
const parseEmails = (cell) => { if(!cell) return []; let s=String(cell).trim().replace(/^\[|\]$/g,''); return s.split(/[,;]+/).map(e=>e.replace(/['"\s]/g,'').trim()).filter(e=>e.includes('@')); };
const keepPublic = (arr) => arr.filter(e=>{ const lp=e.split('@')[0].toLowerCase().split('+')[0]; return !BLACK.has(lp); });
const flat = (r) => { const o={}; for(const k in r){ const v=r[k]; if(v===null||v===undefined) o[k]=''; else if(Array.isArray(v)) o[k]=v.join(', '); else if(typeof v==='object') o[k]=JSON.stringify(v); else o[k]=v; } return o; };
const tag = ((($('Companies Upload').first().json['Tag'])||'')+'').trim();
const rows = $input.all().map(i=>i.json);
const out=[];
for(const r of rows){
  const base=flat(r);
  const emails = keepPublic(parseEmails(r['Public Emails']));
  const cn = cleanCompany(r.Name);
  const meta = { ingested_at:$now.toISO(), Name: cn || (base.Name||''), company_clean:cn, Source:'DiscoLike', Tag:tag };
  if(emails.length) out.push({json:{ ...base, ...meta, segment:'has_public', public_emails_clean:emails.join(', ') }});
  else out.push({json:{ ...base, ...meta, segment:'no_public' }});
}
return out;

const g = ($('Launch Guard').first().json._guard) || {};
const rows = $('Companies Handler').all().map(i=>i.json);
if(!rows.length) return [];
// Operator ruling 2026-08-12: company_clean is retired estate-wide, the cleaned value lives in the
// company column itself (here that is Name). 'Source' is split into 'Contact Source' (where the record
// came from) and 'Email Source' (which waterfall tier found the email, owned by the verification lane).
const DROP = new Set(['_sheet_id','query_name','ingested_at','Tag','company_clean','Source']);
const keys = [];
for(const r of rows){ for(const k in r){ if(!DROP.has(k) && keys.indexOf(k)===-1) keys.push(k); } }
let primary = keys.indexOf('Name')!==-1?'Name':(keys.indexOf('Domain')!==-1?'Domain':keys[0]);
const ordered = [primary].concat(keys.filter(k=>k!==primary));
const EMP=[{name:'1-10'},{name:'11-50'},{name:'51-200'},{name:'201-500'},{name:'501-1000'},{name:'1001-5000'},{name:'5001-10000'},{name:'10001+'}];
const fields = ordered.map(k => (k==='Employees') ? ({ name:'Employees', type:'singleSelect', options:{ choices: EMP } }) : ({ name:k, type:'singleLineText' }));
const have = new Set(fields.map(f=>f.name));
if(!have.has('public_emails_clean')){ fields.push({ name:'public_emails_clean', type:'singleLineText' }); have.add('public_emails_clean'); }
if(!have.has('Tag')){ fields.push({ name:'Tag', type:'singleLineText' }); have.add('Tag'); }
if(!have.has('Contact Source')){ fields.push({ name:'Contact Source', type:'singleLineText' }); have.add('Contact Source'); }
const MV=[{name:'ok',color:'greenBright'},{name:'catch_all',color:'yellowBright'},{name:'invalid',color:'redBright'},{name:'disposable',color:'orangeLight2'},{name:'unknown',color:'grayBright'},{name:'error',color:'orangeBright'},{name:'skipped',color:'grayLight2'}];
const BB=[{name:'verifying',color:'blueBright'},{name:'deliverable',color:'greenBright'},{name:'undeliverable',color:'redBright'},{name:'risky',color:'yellowBright'},{name:'unknown',color:'grayBright'},{name:'error',color:'orangeBright'},{name:'skipped',color:'grayLight2'}];
const STc=[{name:'done',color:'greenBright'},{name:'verifying',color:'blueBright'},{name:'no_email_found',color:'redBright'},{name:'error',color:'orangeBright'}];
const vfields=[ {name:'MV P0',type:'singleSelect',options:{choices:MV}}, {name:'BB',type:'singleSelect',options:{choices:BB}}, {name:'Final Email',type:'singleLineText'}, {name:'Status',type:'singleSelect',options:{choices:STc}} ];
for(const vf of vfields){ if(!have.has(vf.name)){ fields.push(vf); have.add(vf.name); } }
const formulaFields = [{ name:'Build Date', type:'formula', options:{ formula:'CREATED_TIME()' } }];
const desiredName = (g.buildName || 'List') + ' - Domains';
return [{ json: { mode: g.mode, existingTableId: g.existingTableId, buildNameIgnored: !!g.buildNameIgnored, desiredName, fields, formulaFields } }];

const BANDS=['1-10','11-50','51-200','201-500','501-1000','1001-5000','5001-10000','10001+'];
const band=(v)=>{
  const s=String(v==null?'':v).trim();
  if(!s) return '';
  if(BANDS.indexOf(s)>-1) return s;
  const n=Number(s.replace(/[,\s]/g,''));
  if(!isFinite(n)) return s;
  if(n<=0) return '';
  if(n<=10) return '1-10';
  if(n<=50) return '11-50';
  if(n<=200) return '51-200';
  if(n<=500) return '201-500';
  if(n<=1000) return '501-1000';
  if(n<=5000) return '1001-5000';
  if(n<=10000) return '5001-10000';
  return '10001+';
};
const out=[];
for(const it of $('Companies Handler').all()){
  const j = Object.assign({}, it.json);
  delete j._sheet_id; delete j.query_name; delete j.ingested_at;
  // Operator ruling 2026-08-12: company_clean retired, the cleaned name is already in Name.
  delete j.company_clean;
  // 'Source' splits into 'Contact Source' (record provenance) and 'Email Source' (waterfall tier).
  if(Object.prototype.hasOwnProperty.call(j,'Source')){ if(j['Contact Source']===undefined) j['Contact Source']=j.Source; delete j.Source; }
  const d = String(j.Domain==null?'':j.Domain).trim();
  if(!d) continue;
  if(Object.prototype.hasOwnProperty.call(j,'Employees')) j.Employees = band(j.Employees);
  out.push({ json: j });
}
return out;

const form=$('Companies Upload').first().json;
const inCount=$('Read CSV').all().length;
const handled=$('Companies Handler').all();
const total=handled.length;
const hasPublic=handled.filter(i=>i.json.segment==='has_public').length;
const noPublic=handled.filter(i=>i.json.segment==='no_public').length;
let upserted=0; try{ upserted=$('AT Emit Companies').all().length; }catch(e){}
const skipped=Math.max(0, total-upserted);
let clientRec=[];
try{ const rc=$('Resolve Client').first().json; if(rc&&rc.id) clientRec=[rc.id]; }catch(e){}
const g=$('AT Table Guard').first().json||{};
const tableName=g.tableName||'';
const tableId=g.tableId||'';
const modeTxt=(g.mode==='append')?'appended to an existing table':'created a new table';
const fc=(g.fieldsCreated&&g.fieldsCreated.length)?g.fieldsCreated.join(', '):'none';
const tag=((form['Tag']||'')+'').trim();
const start=form.submittedAt;
let dur=0; try{ if(start) dur=Math.max(0,Math.round(($now.toMillis()-new Date(start).getTime())/1000)); }catch(e){}
const trig='form';
const errors=g.createdFieldError?1:0;
const lines=[
'**'+inCount+' domains in, '+upserted+' upserted**',
'',
'**Table:** '+modeTxt+' · '+tableName+' ('+tableId+')',
'',
'**Tag:** '+(tag||'none'),
'',
'**Domains**',
'- **In:** '+inCount,
'- **Upserted:** '+upserted,
'- **With public emails:** '+hasPublic,
'- **Without a public email:** '+noPublic,
'- **Skipped (empty domain):** '+skipped,
'',
'**Fields created:** '+fc
];
if(g.createdFieldError){ lines.push('','**Warning:** '+g.createdFieldError); }
if(g.buildNameIgnored){ lines.push('','**Build name ignored:** an Existing Table ID was supplied.'); }
lines.push('','**Source:** DiscoLike ('+trig+'-launched)');
const log={
  'Automation':'Discolike Domains -> Clayroots',
  'Status': errors?'Succeeded with errors':'Succeeded',
  'Trigger': trig,
  'Errors': errors,
  'Run at': $now.toISO(),
  'Target': tableName+' ('+tableId+')',
  'Records In': inCount,
  'Records Out': upserted,
  'Duration s': dur,
  'Description': lines.join('\n'),
  'Execution Link':'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
  'Execution ID': String($execution.id)
};
if(clientRec.length){ log['Client']=clientRec; } else { delete log['Client']; }
return [{ json: log }];

const j = $input.first().json || {};
if (j && j.mode === 'append') {
  if (!j.tableId) { throw new Error('Table resolution returned no table id: ' + JSON.stringify(j).slice(0,400) + '. Nothing was written.'); }
  return [{ json: { tableId: j.tableId, tableName: j.tableName, mode: 'append', fieldsCreated: j.fieldsCreated || [], buildNameIgnored: !!j.buildNameIgnored, createdFieldError: j.createdFieldError || '' } }];
}
const ct = $('Created Table Guard').first().json || {};
const fr = $('AT Add Created Formula').first().json || {};
if (!fr.id) { throw new Error("Created the table '" + (ct.tableName || '') + "' (" + (ct.tableId || '') + ') but could not add the computed Build Date field: ' + JSON.stringify(fr).slice(0,300) + '. Nothing was written.'); }
const fieldsCreated = (ct.fieldNames || []).concat([fr.name || 'Build Date']);
return [{ json: { tableId: ct.tableId, tableName: ct.tableName, mode: 'create', fieldsCreated, buildNameIgnored: false, createdFieldError: '' } }];

const rec=$('Fetch Launch Record').first().json;
const f=rec.fields||{};
const cf=($('Resolve Base').first().json.fields)||{};
const att=(f['Attachment']||[])[0]||{};
if(!att.url){ throw new Error('Launch record '+rec.id+' has no Attachment CSV.'); }
const tid = (((f['Table ID']||'')+'').trim()) || (((f['Target']||'')+'').trim());
return [{ json: {
  'Clayroots Base ID': ((cf['Clayroots Base ID']||'')+'').trim(),
  'Build name': ((f['Build name']||'')+'').trim(),
  'Existing Table ID': tid,
  'Tag': ((f['Tag']||'')+'').trim(),
  'CSV': { filename: att.filename||'launch.csv', mimetype: att.type||'text/csv' },
  '_launchRecordId': rec.id,
  'submittedAt': new Date().toISOString()
} }];

const params=$('Launch Params').first().json;
const bin=$input.first().binary||{};
const data=bin.data||Object.values(bin)[0];
if(!data){ throw new Error('Download CSV returned no binary data.'); }
return [{ json: params, binary: { 'CSV': data } }];

const items = $input.all();
const f = (items[0] && items[0].json) ? items[0].json : {};
const build = ((f['Build name'] || '') + '').trim();
const tid = ((f['Existing Table ID'] || '') + '').trim();
if (!build && !tid) { throw new Error('Provide a Build name (to create a new table) or an Existing Table ID (to append to one). Nothing was written.'); }
if (tid && !/^tbl[A-Za-z0-9]{14}$/.test(tid)) { throw new Error('Existing Table ID "' + tid + '" is not a valid Airtable table id (expected tbl followed by 14 characters). Nothing was written.'); }
const g = { buildName: build, existingTableId: tid, mode: tid ? 'append' : 'create', buildNameIgnored: !!(tid && build) };
return items.map(i => ({ json: Object.assign({}, i.json, { _guard: g }), binary: i.binary }));

const spec = $('AT Schema Companies').first().json;
const baseId = (($('Companies Upload').first().json['Clayroots Base ID'])||'').trim();
const resp = $('AT List Tables').first().json || {};
const tables = Array.isArray(resp.tables) ? resp.tables : null;
if (!tables) { throw new Error('Could not read the table list for base ' + baseId + ': ' + JSON.stringify(resp).slice(0,400) + '. Nothing was written.'); }
const plain = spec.fields || [];
const formulas = spec.formulaFields || [];
if (spec.mode !== 'append') {
  const taken = new Set(tables.map(t => String(t.name)));
  let name = spec.desiredName; let n = 1;
  while (taken.has(name)) { n++; name = spec.desiredName + ' (' + n + ')'; }
  return [{ json: { mode: 'create', createName: name, fields: plain, missing: formulas, missingNames: formulas.map(f => f.name), buildNameIgnored: false } }];
}
const target = tables.find(t => t.id === spec.existingTableId);
if (!target) { throw new Error('Table ' + spec.existingTableId + ' does not exist in base ' + baseId + '. Tables there: ' + tables.map(t => t.name).join(', ') + '. Nothing was written.'); }
if (/contacts/i.test(String(target.name || ''))) { throw new Error("Refusing to write domains into '" + target.name + "' - that table is a contacts table. Nothing was written."); }
const norm = (s) => String(s == null ? '' : s).trim().toLowerCase();
const targetFields = target.fields || [];
const existing = new Map(targetFields.map(f => [f.name, f]));
const existingCI = new Map(targetFields.map(f => [norm(f.name), f]));
const COMPUTED = new Set(formulas.map(f => f.name));
const kind = (ty) => ty === 'number' ? 'number' : (ty === 'singleSelect' ? 'select' : (ty === 'date' ? 'date' : 'text'));
const okWith = { number: ['number'], text: ['singleLineText','multilineText','singleSelect'], select: ['singleSelect','singleLineText'], date: ['date','dateTime'] };
const contract = plain.concat(formulas);
const clashes = []; const missing = [];
for (const cf of contract) {
  if (COMPUTED.has(cf.name)) {
    const ex = existingCI.get(norm(cf.name));
    if (!ex) { missing.push(cf); continue; }
    if (ex.type !== 'formula') { throw new Error("Table '" + target.name + "' (" + target.id + ') still has a writable ' + cf.name + ' (type: ' + ex.type + '). Convert it to a CREATED_TIME() formula field before building. Nothing was written.'); }
    continue;
  }
  const ex = existing.get(cf.name);
  if (!ex) { missing.push(cf); continue; }
  if (!okWith[kind(cf.type)].includes(ex.type)) { clashes.push(cf.name + ' (type in table: ' + ex.type + ', type expected: ' + cf.type + ')'); }
}
if (clashes.length) { throw new Error("Type clash in table '" + target.name + "' (" + target.id + '): ' + clashes.join('; ') + '. Nothing was written.'); }
return [{ json: { mode: 'append', tableId: target.id, tableName: target.name, fields: contract, missing, missingNames: missing.map(f => f.name), buildNameIgnored: !!spec.buildNameIgnored } }];

const r = $('Table Router').first().json;
let rows = [];
try { rows = $('AT Read Domains').all().map(i => i.json || {}); } catch (e) { rows = []; }
const counts = new Map();
for (const it of rows) {
  const raw = (it.Domain !== undefined) ? it.Domain : ((it.fields || {}).Domain);
  const d = String(raw == null ? '' : raw).trim().toLowerCase();
  if (!d) continue;
  counts.set(d, (counts.get(d) || 0) + 1);
}
const dups = Array.from(counts.entries()).filter(e => e[1] > 1).map(e => e[0]);
if (dups.length) { throw new Error("Target table '" + r.tableName + "' has repeated Domain values (e.g. " + dups.slice(0,3).join(', ') + '), which means it is contact-shaped. Refusing to upsert on Domain. Nothing was written.'); }
return [{ json: Object.assign({}, r, { fieldsCreated: [], domainsChecked: counts.size }) }];

const r = $('Table Router').first().json;
const baseId = (($('Companies Upload').first().json['Clayroots Base ID'])||'').trim();
const resp = $('AT Verify Schema').first().json || {};
const tables = Array.isArray(resp.tables) ? resp.tables : null;
if (!tables) { throw new Error('Could not re-read the schema of base ' + baseId + ' after creating fields: ' + JSON.stringify(resp).slice(0,400) + '. Nothing was written.'); }
const target = tables.find(t => t.id === r.tableId);
if (!target) { throw new Error('Table ' + r.tableId + ' is no longer present in base ' + baseId + '. Nothing was written.'); }
const norm = (s) => String(s == null ? '' : s).trim().toLowerCase();
const have = new Set((target.fields || []).map(f => norm(f.name)));
const still = (r.fields || []).filter(f => !have.has(norm(f.name))).map(f => f.name);
if (still.length) { throw new Error("Could not create these fields on '" + target.name + "' (" + target.id + '): ' + still.join(', ') + '. Nothing was written.'); }
const wanted = r.missingNames || [];
const created = wanted.filter(n => have.has(norm(n)));
return [{ json: { mode: 'append', tableId: target.id, tableName: target.name, fieldsCreated: created, buildNameIgnored: !!r.buildNameIgnored, createdFieldError: '' } }];

const j = $input.first().json || {};
const baseId = (($('Companies Upload').first().json['Clayroots Base ID'])||'').trim();
if (!j.id) { throw new Error('Airtable build-table creation failed in base ' + baseId + ': ' + JSON.stringify(j).slice(0,400) + '. Nothing was written.'); }
return [{ json: { tableId: j.id, tableName: j.name, fieldNames: (j.fields || []).map(f => f.name) } }];
